using System;using System.Windows.Forms;using AshkanJobCenter.Core;using AshkanJobCenter.Data;namespace AshkanJobCenter.UI{public class SettingsPage:UserControl{public SettingsPage(){var f=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,Padding=new Padding(20),WrapContents=false};f.Controls.Add(Ui.Label(L.Fa?"تنظیمات سامانه":"System settings",18,true));f.Controls.Add(Ui.Label(L.Fa?"زبان رابط کاربری":"Interface language"));var lang=Ui.Button(L.Fa?"Switch to English":"تغییر به فارسی",false);lang.Click+=(s,e)=>{AppSession.Language=L.Fa?"en":"fa";MessageBox.Show(L.Fa?"زبان تغییر کرد. برای اعمال کامل، یک بار وارد سامانه شوید.":"Language changed. Sign in again to fully apply it.");};f.Controls.Add(lang);f.Controls.Add(Ui.Label(L.Fa?"پایگاه داده":"Database",12,true));f.Controls.Add(Ui.Label("SQL Server LocalDB • .NET Framework 4.8"));f.Controls.Add(Ui.Label(L.Fa?"امنیت":"Security",12,true));f.Controls.Add(Ui.Label(L.Fa?"رمزهای عبور با SHA-256 + Salt ذخیره می‌شوند و عملیات مدیریتی Audit می‌شود.":"Passwords are salted + hashed and administrative actions are audited."));Controls.Add(f);}}}